"""Figure for the activation study -> reports/figures/bl_act_logic.png"""
import sys, os, warnings; sys.path.insert(0, '.'); warnings.filterwarnings('ignore')
import numpy as np, pandas as pd, json, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
from bl_common import OUT
FIG = os.path.join(os.path.dirname(OUT), 'reports', 'figures'); os.makedirs(FIG, exist_ok=True)
D = pd.read_csv(f'{OUT}/bl_act_dirs.csv'); GA = pd.read_csv(f'{OUT}/bl_act_gap_auc.csv'); GB = pd.read_csv(f'{OUT}/bl_act_gb.csv').set_index('model').LOCO_AUC; R4 = json.load(open(f'{OUT}/bl_summary_act4.json'))
fig, ax = plt.subplots(2, 2, figsize=(13.5, 9.5))
a = ax[0, 0]; d = D.sort_values('hit_rate'); trend = d['reference X (direction = sign of live spot - X)'].str.startswith(('spot', 'SMA')); a.barh(range(len(d)), d.hit_rate * 100, color=['#d62728' if t else '#1f77b4' for t in trend]); a.set_yticks(range(len(d))); a.set_yticklabels(d['reference X (direction = sign of live spot - X)'], fontsize=7); a.set_xlabel('% of reactive pairs whose strike = live ATM + 1 step toward sign(live spot - X)'); a.set_title('A. Direction: live spot vs a trailing price (red) beats book anchors (blue)')
a = ax[0, 1]; a.plot(GA.N_min, GA.AUC_abs_gap, 'o-', color='#d62728', label='|spot − moving average of N min|'); a.fill_between(GA.N_min, GA.lo, GA.hi, color='#d62728', alpha=.15); a.plot(GA.N_min, GA.AUC_abs_move_L, 's--', color='#7f7f7f', label='|spot − spot N min ago|'); a.axhline(.5, color='k', ls=':', lw=1); a.set_xscale('log'); a.set_xticks([3, 5, 10, 15, 30, 60, 120]); a.set_xticklabels([3, 5, 10, 15, 30, 60, 120]); a.set_xlabel('N (minutes)'); a.set_ylabel('AUC for reactive-pair minutes (causal, 10:30–15:15)'); a.set_title('B. The gap to a moving average separates better than a plain move'); a.legend(fontsize=8)
a = ax[1, 0]; h = pd.DataFrame(R4['hazard_bins']); a.bar(range(len(h)), h.per1000, color='#ff7f0e'); a.set_xticks(range(len(h))); a.set_xticklabels([str(x).replace('(', '').replace(']', '').replace(', ', '–') for x in h.absg], rotation=40, fontsize=7); a.set_xlabel('|live spot − 60-min average|, in strike steps'); a.set_ylabel('reactive pairs per 1000 cycle-minutes'); a.set_title('C. A dead zone: almost no pairs when the spot sits on its average')
for i, (e, n) in enumerate(zip(h['sum'], h['size'])): a.text(i, h.per1000.iloc[i] + 1, f'{int(e)}/{int(n)}', ha='center', fontsize=6)
a = ax[1, 1]; labs = ['clock\nonly', '+ order-\nactivity ages', '+ spot position\n(causal)', 'causal\nall blocks', 'causal + current-\nminute move', 'live-spot\nproxy, all']; vals = [GB['clock only'], GB['clock + ages'], GB['CAUSAL (completed bars only): clock + ages + spot_position'], GB['CAUSAL: all blocks'], GB['CAUSAL: all blocks + current-minute move (look-ahead)'], GB['LIVE-PROXY all blocks']]
a.bar(range(6), vals, color=['#7f7f7f', '#1f77b4', '#d62728', '#8c564b', '#bcbd22', '#000000']); a.set_ylim(.5, .95); a.set_xticks(range(6)); a.set_xticklabels(labs, fontsize=7); a.set_ylabel('leave-one-cycle-out AUC, events vs random seconds'); a.set_title('D. What separates a reactive-pair second from a random second')
for i, v in enumerate(vals): a.text(i, v + .005, f'{v:.3f}', ha='center', fontsize=8)
fig.suptitle('Algo 8 reactive pairs: dynamic reference and activation — in-sample, D-1, 363 pairs', fontsize=11); fig.tight_layout(); fig.savefig(f'{FIG}/bl_act_logic.png', dpi=140); print('saved')
